from ortools.linear_solver import pywraplp
import itertools
import json

def main():
    N = list(range(1, 8))
    p = 3

    c = {}
    c[(1, 2)] = 10
    c[(1, 3)] = 5
    c[(1, 4)] = 8
    c[(1, 5)] = 12
    c[(1, 6)] = 15
    c[(1, 7)] = 20
    c[(2, 3)] = 7
    c[(2, 4)] = 6
    c[(2, 5)] = 9
    c[(2, 6)] = 11
    c[(2, 7)] = 18
    c[(3, 4)] = 4
    c[(3, 5)] = 14
    c[(3, 6)] = 16
    c[(3, 7)] = 22
    c[(4, 5)] = 3
    c[(4, 6)] = 13
    c[(4, 7)] = 17
    c[(5, 6)] = 2
    c[(5, 7)] = 19
    c[(6, 7)] = 25

    for (i, j), val in list(c.items()):
        c[(j, i)] = val

    INF = float('inf')
    n = len(N)

    d = [[INF] * (n + 1) for _ in range(n + 1)]

    for i in N:
        d[i][i] = 0

    for (i, j), val in c.items():
        d[i][j] = val

    for k in N:
        for i in N:
            for j in N:
                if d[i][k] + d[k][j] < d[i][j]:
                    d[i][j] = d[i][k] + d[k][j]

    solver = pywraplp.Solver.CreateSolver('SCIP')
    INF = solver.infinity()

    y = {}
    for i in N:
        y[i] = solver.BoolVar(f'y[{i}]')

    x = {}
    for i in N:
        for j in N:
            x[(i, j)] = solver.BoolVar(f'x[{i},{j}]')

    solver.Add(sum(y[i] for i in N) == p)

    for i in N:
        solver.Add(sum(x[(i, j)] for j in N) == 1)

    for i in N:
        for j in N:
            solver.Add(x[(i, j)] <= y[j])

    for j in N:
        solver.Add(x[(j, j)] >= y[j])

    objective = solver.Sum(d[i][j] * x[(i, j)] for i in N for j in N)
    solver.Minimize(objective)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        hubs = [i for i in N if y[i].solution_value() > 0.5]

        assignments = {}
        for i in N:
            for j in N:
                if x[(i, j)].solution_value() > 0.5:
                    assignments[i] = j
                    break

        total_latency = solver.Objective().Value()

        neural_connectivity_assignments = []
        for i in sorted(N):
            hub = assignments[i]
            latency = d[i][hub]
            if i == hub:
                path = [i]
            else:
                path = [i, hub]
            neural_connectivity_assignments.append([hub, path, latency])

        result = {
            "cognitive_processing_hubs": sorted(hubs),
            "total_computational_latency": int(total_latency),
            "neural_connectivity_assignments": neural_connectivity_assignments
        }
        print(json.dumps(result))
    else:
        print(f"No optimal solution found. Status: {status}")

if __name__ == '__main__':
    main()
